INSERT INTO curriculum_nodes (id, slug, phase_id, order_index, title, subtitle, cs_foundation, ai_convergence, xp_reward, level_required, position_x, position_y, handbook_markdown, starter_code, test_suite, defense_prompts) VALUES
('node-7-21', 'phase-07-lesson-21-kubernetes-configuration-configmaps-secre', 'module-10', 21, 'Lesson 10.21: Kubernetes Configuration: ConfigMaps, Secrets, External Secrets & SOPS', 'Prerequisites: Phase 5, Lesson 7.16', 'Prerequisites: Phase 5, Lesson 7.16 | Subtopics: 6 items', 'Systems project application', 240, 8, 1750.0, 1050.0, '# Lesson 7.21: Kubernetes Configuration: ConfigMaps, Secrets, External Secrets & SOPS

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 5, Lesson 7.16
- **Subtopics**:
  - `7.21.1` ConfigMap architecture: environment variable injection vs mounted volume directories, subPath pitfalls, and atomic updates
  - `7.21.2` Kubernetes Secrets: base64 encoding limitations, encryption at rest in etcd using KMS envelope encryption
  - `7.21.3` External Secrets Operator (ESO): synchronizing secrets securely from Google Cloud Secret Manager / HashiCorp Vault into Kubernetes
  - `7.21.4` GitOps secrets management: Mozilla SOPS, age encryption, and SealedSecrets for safe repository storage
  - `7.21.5` Secret rotation workflows: dynamic pod reloads via Stakater Reloader vs in-memory application watcher loops
  - `7.21.6` Preventing secrets leakage: restricting RBAC `secrets` permissions and disabling secret environment variable reflection in crash logs
- **Key Failure Modes & Edge Cases**: Treating raw Kubernetes base64 Secrets as secure; subPath volume mounts failing to receive live ConfigMap updates.
- **Verification & Mastery Check**: Implement External Secrets Operator synchronizing credentials from GCP Secret Manager with automated pod rolling updates on rotation.
- **Project Application**: InfraBlueprint: Production secret management pipeline with ESO.', '{"solution.py": "# Phase 7 // Lesson 7.21: Kubernetes Configuration: ConfigMaps, Secrets, External Secrets & SOPS\n\ndef solve():\n    \"\"\"\n    Verification: Implement External Secrets Operator synchronizing credentials from GCP Secret Manager with automated\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "7.21", "subtopics_count": 6, "verification_criteria": "Implement External Secrets Operator synchronizing credentials from GCP Secret Manager with automated pod rolling updates on rotation.", "subtopics": ["7.21.1 ConfigMap architecture: environment variable injection vs mounted volume directories, subPath pitfalls, and atomic updates", "7.21.2 Kubernetes Secrets: base64 encoding limitations, encryption at rest in etcd using KMS envelope encryption", "7.21.3 External Secrets Operator (ESO): synchronizing secrets securely from Google Cloud Secret Manager / HashiCorp Vault into Kubernetes", "7.21.4 GitOps secrets management: Mozilla SOPS, age encryption, and SealedSecrets for safe repository storage", "7.21.5 Secret rotation workflows: dynamic pod reloads via Stakater Reloader vs in-memory application watcher loops", "7.21.6 Preventing secrets leakage: restricting RBAC `secrets` permissions and disabling secret environment variable reflection in crash logs"]}'::jsonb, '["Explain how this implementation prevents: Treating raw Kubernetes base64 Secrets as secure; subPath volume mounts failing to receive live ConfigMap updates.", "How does Kubernetes Configuration: ConfigMaps, Secrets, External Secrets & SOPS scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-7-22', 'phase-07-lesson-22-kubernetes-security-rbac-pod-security-sta', 'module-10', 22, 'Lesson 10.22: Kubernetes Security: RBAC, Pod Security Standards & NetworkPolicies', 'Prerequisites: Phase 5, Lesson 7.15', 'Prerequisites: Phase 5, Lesson 7.15 | Subtopics: 6 items', 'Systems project application', 240, 8, 1810.0, 1100.0, '# Lesson 7.22: Kubernetes Security: RBAC, Pod Security Standards & NetworkPolicies

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 5, Lesson 7.15
- **Subtopics**:
  - `7.22.1` Role-Based Access Control (RBAC): Roles, ClusterRoles, RoleBindings, and ClusterRoleBindings principle of least privilege
  - `7.22.2` ServiceAccounts: automountServiceAccountToken dangers, projected service account tokens, and short-lived credentials
  - `7.22.3` Pod Security Standards (PSS): Privileged, Baseline, and Restricted admission levels enforced via namespace labels
  - `7.22.4` Hardening security contexts: `runAsNonRoot: true`, `readOnlyRootFilesystem: true`, `allowPrivilegeEscalation: false`
  - `7.22.5` Kubernetes NetworkPolicies: default-deny ingress and egress rules, podSelector, and namespaceSelector enforcement
  - `7.22.6` Runtime container auditing: Falco eBPF security monitoring detecting anomalous shell spawning and root file modifications
- **Key Failure Modes & Edge Cases**: Wildcard `*` verbs in ClusterRoles granting cluster-admin privileges; un-isolated namespaces allowing cross-tenant pod network tapping.
- **Verification & Mastery Check**: Construct a hardened namespace with Restricted PSS, non-root security contexts, and default-deny NetworkPolicies blocking unauthorized egress.
- **Project Application**: InfraBlueprint: Zero-trust Kubernetes security hardening manifests.', '{"solution.py": "# Phase 7 // Lesson 7.22: Kubernetes Security: RBAC, Pod Security Standards & NetworkPolicies\n\ndef solve():\n    \"\"\"\n    Verification: Construct a hardened namespace with Restricted PSS, non-root security contexts, and default-deny Net\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "7.22", "subtopics_count": 6, "verification_criteria": "Construct a hardened namespace with Restricted PSS, non-root security contexts, and default-deny NetworkPolicies blocking unauthorized egress.", "subtopics": ["7.22.1 Role-Based Access Control (RBAC): Roles, ClusterRoles, RoleBindings, and ClusterRoleBindings principle of least privilege", "7.22.2 ServiceAccounts: automountServiceAccountToken dangers, projected service account tokens, and short-lived credentials", "7.22.3 Pod Security Standards (PSS): Privileged, Baseline, and Restricted admission levels enforced via namespace labels", "7.22.4 Hardening security contexts: `runAsNonRoot: true`, `readOnlyRootFilesystem: true`, `allowPrivilegeEscalation: false`", "7.22.5 Kubernetes NetworkPolicies: default-deny ingress and egress rules, podSelector, and namespaceSelector enforcement", "7.22.6 Runtime container auditing: Falco eBPF security monitoring detecting anomalous shell spawning and root file modifications"]}'::jsonb, '["Explain how this implementation prevents: Wildcard `*` verbs in ClusterRoles granting cluster-admin privileges; un-isolated namespaces allowing cross-tenant pod n", "How does Kubernetes Security: RBAC, Pod Security Standards & NetworkPolicies scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-7-23', 'phase-07-lesson-23-kubernetes-autoscaling-hpa-vpa-cluster-au', 'module-10', 23, 'Lesson 10.23: Kubernetes Autoscaling: HPA, VPA & Cluster Autoscaler / Karpenter', 'Prerequisites: Lesson 7.16, Lesson 7.18', 'Prerequisites: Lesson 7.16, Lesson 7.18 | Subtopics: 6 items', 'Systems project application', 240, 8, 1870.0, 1150.0, '# Lesson 7.23: Kubernetes Autoscaling: HPA, VPA & Cluster Autoscaler / Karpenter

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 7.16, Lesson 7.18
- **Subtopics**:
  - `7.23.1` Horizontal Pod Autoscaler (HPA v2): scaling based on CPU/memory utilization and custom metrics (Prometheus metrics adapter)
  - `7.23.2` HPA scaling algorithm: $\text{desiredReplicas} = \lceil \text{currentReplicas} \times (\text{currentMetricValue} / \text{desiredMetricValue}) \rceil$
  - `7.23.3` HPA stabilization windows and rate-limiting scaling behavior to prevent rapid flapping (thrashing)
  - `7.23.4` Vertical Pod Autoscaler (VPA): Recommender, Updater, and Admission Controller automatically tuning CPU/memory requests
  - `7.23.5` Cluster Autoscaler (CA): scaling node groups based on pending unschedulable pods and underutilized node drain conditions
  - `7.23.6` Karpenter high-performance autoscaling: node-less direct EC2/GCE instance provisioning bypassing managed node groups for rapid scale-up
- **Key Failure Modes & Edge Cases**: HPA and VPA conflicting on the same resource metrics causing oscillating scale actions; scaling lag dropping traffic during sharp traffic spikes.
- **Verification & Mastery Check**: Configure HPA scaling an API service based on real-time HTTP requests-per-second custom metrics from Prometheus; stress-test with k6.
- **Project Application**: InfraBlueprint: Metric-driven horizontal autoscaling engine.', '{"solution.py": "# Phase 7 // Lesson 7.23: Kubernetes Autoscaling: HPA, VPA & Cluster Autoscaler / Karpenter\n\ndef solve():\n    \"\"\"\n    Verification: Configure HPA scaling an API service based on real-time HTTP requests-per-second custom metrics from\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "7.23", "subtopics_count": 6, "verification_criteria": "Configure HPA scaling an API service based on real-time HTTP requests-per-second custom metrics from Prometheus; stress-test with k6.", "subtopics": ["7.23.1 Horizontal Pod Autoscaler (HPA v2): scaling based on CPU/memory utilization and custom metrics (Prometheus metrics adapter)", "7.23.2 HPA scaling algorithm: $\\text{desiredReplicas} = \\lceil \\text{currentReplicas} \\times (\\text{currentMetricValue} / \\text{desiredMetricValue}) \\rceil$", "7.23.3 HPA stabilization windows and rate-limiting scaling behavior to prevent rapid flapping (thrashing)", "7.23.4 Vertical Pod Autoscaler (VPA): Recommender, Updater, and Admission Controller automatically tuning CPU/memory requests", "7.23.5 Cluster Autoscaler (CA): scaling node groups based on pending unschedulable pods and underutilized node drain conditions", "7.23.6 Karpenter high-performance autoscaling: node-less direct EC2/GCE instance provisioning bypassing managed node groups for rapid scale-up"]}'::jsonb, '["Explain how this implementation prevents: HPA and VPA conflicting on the same resource metrics causing oscillating scale actions; scaling lag dropping traffic dur", "How does Kubernetes Autoscaling: HPA, VPA & Cluster Autoscaler / Karpenter scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-7-24', 'phase-07-lesson-24-kubernetes-extensibility-custom-resource-', 'module-10', 24, 'Lesson 10.24: Kubernetes Extensibility: Custom Resource Definitions (CRDs) & Operator SDK', 'Prerequisites: Phase 1, Lesson 7.15', 'Prerequisites: Phase 1, Lesson 7.15 | Subtopics: 6 items', 'Systems project application', 240, 8, 1750.0, 1200.0, '# Lesson 7.24: Kubernetes Extensibility: Custom Resource Definitions (CRDs) & Operator SDK

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 1, Lesson 7.15
- **Subtopics**:
  - `7.24.1` Custom Resource Definitions (CRD): extending the Kubernetes API with OpenAPI v3 validation schemas and subresources (`/status`, `/scale`)
  - `7.24.2` The Operator Pattern: encoding human operational domain knowledge into software automation loops
  - `7.24.3` Controller runtime architecture: Informers, SharedIndexInformer, Lister caches, work queues, and reconciliation loops
  - `7.24.4` Level-triggered vs Edge-triggered control loops: why reconciliation must be idempotent and resilient to missed events
  - `7.24.5` Building an Operator with Kubebuilder / Operator SDK: scaffolding controllers, generating RBAC manifests, and manager lifecycle
  - `7.24.6` Validating and Mutating Admission Webhooks: intercepting, mutating, and rejecting custom resource submissions
- **Key Failure Modes & Edge Cases**: Writing non-idempotent reconciliation loops causing infinite update loops against the Kubernetes API server.
- **Verification & Mastery Check**: Build a production Kubernetes Operator in Go that provisions and monitors Postgres database instances on-demand via custom resources.
- **Project Application**: InfraBlueprint: Custom Database Provisioning Operator.', '{"solution.py": "# Phase 7 // Lesson 7.24: Kubernetes Extensibility: Custom Resource Definitions (CRDs) & Operator SDK\n\ndef solve():\n    \"\"\"\n    Verification: Build a production Kubernetes Operator in Go that provisions and monitors Postgres database instance\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "7.24", "subtopics_count": 6, "verification_criteria": "Build a production Kubernetes Operator in Go that provisions and monitors Postgres database instances on-demand via custom resources.", "subtopics": ["7.24.1 Custom Resource Definitions (CRD): extending the Kubernetes API with OpenAPI v3 validation schemas and subresources (`/status`, `/scale`)", "7.24.2 The Operator Pattern: encoding human operational domain knowledge into software automation loops", "7.24.3 Controller runtime architecture: Informers, SharedIndexInformer, Lister caches, work queues, and reconciliation loops", "7.24.4 Level-triggered vs Edge-triggered control loops: why reconciliation must be idempotent and resilient to missed events", "7.24.5 Building an Operator with Kubebuilder / Operator SDK: scaffolding controllers, generating RBAC manifests, and manager lifecycle", "7.24.6 Validating and Mutating Admission Webhooks: intercepting, mutating, and rejecting custom resource submissions"]}'::jsonb, '["Explain how this implementation prevents: Writing non-idempotent reconciliation loops causing infinite update loops against the Kubernetes API server.", "How does Kubernetes Extensibility: Custom Resource Definitions (CRDs) & Operator SDK scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-7-25', 'phase-07-lesson-25-helm-packaging-kustomize-overlays-configu', 'module-10', 25, 'Lesson 10.25: Helm Packaging, Kustomize Overlays & Configuration Management', 'Prerequisites: Lesson 7.16, Lesson 7.21', 'Prerequisites: Lesson 7.16, Lesson 7.21 | Subtopics: 6 items', 'Systems project application', 240, 8, 1810.0, 1250.0, '# Lesson 7.25: Helm Packaging, Kustomize Overlays & Configuration Management

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 7.16, Lesson 7.21
- **Subtopics**:
  - `7.25.1` Helm architecture: chart structure, values.yaml, Go template functions, built-in objects, and release management
  - `7.25.2` Helm lifecycle hooks: pre-install, post-install, pre-upgrade hooks for database migrations and schema checks
  - `7.25.3` Kustomize declarative configuration: template-free customization using base and environment overlays (dev, staging, prod)
  - `7.25.4` Kustomize transformations: patches, configMapGenerators, secretGenerators, and image tag substitutions
  - `7.25.5` Helm vs Kustomize comparison: parameterized packages vs declarative overlay composition, and combining Helm with Kustomize
  - `7.25.6` Validating manifests: `kubeconform`, `conftest` (Rego policies), and static linting in CI before cluster deployment
- **Key Failure Modes & Edge Cases**: Template expansion rendering invalid YAML; unpinned chart dependencies pulling breaking changes into production releases.
- **Verification & Mastery Check**: Build a base Kustomize architecture with staging/production overlays patching replica counts, resources, and environment secrets.
- **Project Application**: InfraBlueprint: Enterprise Kustomize configuration repository.', '{"solution.py": "# Phase 7 // Lesson 7.25: Helm Packaging, Kustomize Overlays & Configuration Management\n\ndef solve():\n    \"\"\"\n    Verification: Build a base Kustomize architecture with staging/production overlays patching replica counts, resour\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "7.25", "subtopics_count": 6, "verification_criteria": "Build a base Kustomize architecture with staging/production overlays patching replica counts, resources, and environment secrets.", "subtopics": ["7.25.1 Helm architecture: chart structure, values.yaml, Go template functions, built-in objects, and release management", "7.25.2 Helm lifecycle hooks: pre-install, post-install, pre-upgrade hooks for database migrations and schema checks", "7.25.3 Kustomize declarative configuration: template-free customization using base and environment overlays (dev, staging, prod)", "7.25.4 Kustomize transformations: patches, configMapGenerators, secretGenerators, and image tag substitutions", "7.25.5 Helm vs Kustomize comparison: parameterized packages vs declarative overlay composition, and combining Helm with Kustomize", "7.25.6 Validating manifests: `kubeconform`, `conftest` (Rego policies), and static linting in CI before cluster deployment"]}'::jsonb, '["Explain how this implementation prevents: Template expansion rendering invalid YAML; unpinned chart dependencies pulling breaking changes into production releases", "How does Helm Packaging, Kustomize Overlays & Configuration Management scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-7-26', 'phase-07-lesson-26-gitops-continuous-delivery-argocd-fluxcd-', 'module-10', 26, 'Lesson 10.26: GitOps Continuous Delivery: ArgoCD & FluxCD Engine', 'Prerequisites: Lesson 7.24, Lesson 7.25', 'Prerequisites: Lesson 7.24, Lesson 7.25 | Subtopics: 6 items', 'Systems project application', 240, 8, 1870.0, 1300.0, '# Lesson 7.26: GitOps Continuous Delivery: ArgoCD & FluxCD Engine

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 7.24, Lesson 7.25
- **Subtopics**:
  - `7.26.1` GitOps principles: declarative descriptions, version-controlled source of truth, automated pull-based state convergence
  - `7.26.2` Push-based CI/CD (Jenkins, GitLab CI) vs Pull-based GitOps (ArgoCD): eliminating long-lived cluster credentials in CI
  - `7.26.3` ArgoCD architecture: Application controller, API server, repository server, and custom resource definitions (Application, AppProject)
  - `7.26.4` Sync policies: automated sync, self-healing, pruning unmanaged resources, and sync waves for ordered resource provisioning
  - `7.26.5` Managing multi-tenant clusters with App-of-Apps and ApplicationSet generators (Git directory, cluster, and matrix generators)
  - `7.26.6` Disaster recovery via GitOps: reconstructing an entire multi-node cluster from scratch exclusively from the Git repository
- **Key Failure Modes & Edge Cases**: Disabling automated pruning leading to orphaned, zombie resources lingering in clusters; Git commit loops from automated in-cluster updates.
- **Verification & Mastery Check**: Deploy a multi-environment microservice fleet using ArgoCD with sync waves, automated self-healing, and Slack deployment notifications.
- **Project Application**: InfraBlueprint: ArgoCD continuous delivery pipeline.', '{"solution.py": "# Phase 7 // Lesson 7.26: GitOps Continuous Delivery: ArgoCD & FluxCD Engine\n\ndef solve():\n    \"\"\"\n    Verification: Deploy a multi-environment microservice fleet using ArgoCD with sync waves, automated self-healing, \n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "7.26", "subtopics_count": 6, "verification_criteria": "Deploy a multi-environment microservice fleet using ArgoCD with sync waves, automated self-healing, and Slack deployment notifications.", "subtopics": ["7.26.1 GitOps principles: declarative descriptions, version-controlled source of truth, automated pull-based state convergence", "7.26.2 Push-based CI/CD (Jenkins, GitLab CI) vs Pull-based GitOps (ArgoCD): eliminating long-lived cluster credentials in CI", "7.26.3 ArgoCD architecture: Application controller, API server, repository server, and custom resource definitions (Application, AppProject)", "7.26.4 Sync policies: automated sync, self-healing, pruning unmanaged resources, and sync waves for ordered resource provisioning", "7.26.5 Managing multi-tenant clusters with App-of-Apps and ApplicationSet generators (Git directory, cluster, and matrix generators)", "7.26.6 Disaster recovery via GitOps: reconstructing an entire multi-node cluster from scratch exclusively from the Git repository"]}'::jsonb, '["Explain how this implementation prevents: Disabling automated pruning leading to orphaned, zombie resources lingering in clusters; Git commit loops from automated", "How does GitOps Continuous Delivery: ArgoCD & FluxCD Engine scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-7-27', 'phase-07-lesson-27-cloud-foundations-google-cloud-platform-g', 'module-10', 27, 'Lesson 10.27: Cloud Foundations: Google Cloud Platform (GCP) Resource Hierarchy & IAM', 'Prerequisites: Phase 5, Lesson 7.1', 'Prerequisites: Phase 5, Lesson 7.1 | Subtopics: 6 items', 'Systems project application', 240, 8, 1750.0, 1350.0, '# Lesson 7.27: Cloud Foundations: Google Cloud Platform (GCP) Resource Hierarchy & IAM

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 5, Lesson 7.1
- **Subtopics**:
  - `7.27.1` GCP Resource Hierarchy: Organization, Folders, Projects, and Resources; policy inheritance and overriding rules
  - `7.27.2` GCP Identity and Access Management (IAM): Principal, Roles (Primitive, Predefined, Custom), and Permissions ($service.resource.action)
  - `7.27.3` IAM Conditions: context-aware access based on date/time, destination IP, resource tags, and request attributes
  - `7.27.4` Service Accounts: user-managed vs default service accounts, service account keys security vulnerabilities, and keyless architectures
  - `7.27.5` Workload Identity Federation: mapping external identities (GitHub Actions, AWS) to GCP IAM without static credentials
  - `7.27.6` GKE Workload Identity: binding Kubernetes ServiceAccounts directly to GCP ServiceAccounts via annotations and OIDC
- **Key Failure Modes & Edge Cases**: Using default Compute Engine service accounts with broad Editor privileges; committing JSON service account keys to Git.
- **Verification & Mastery Check**: Configure keyless CI/CD deployments from GitHub Actions to GCP using Workload Identity Federation with restricted custom IAM roles.
- **Project Application**: InfraBlueprint: GCP enterprise resource hierarchy and keyless IAM architecture.', '{"solution.py": "# Phase 7 // Lesson 7.27: Cloud Foundations: Google Cloud Platform (GCP) Resource Hierarchy & IAM\n\ndef solve():\n    \"\"\"\n    Verification: Configure keyless CI/CD deployments from GitHub Actions to GCP using Workload Identity Federation wi\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "7.27", "subtopics_count": 6, "verification_criteria": "Configure keyless CI/CD deployments from GitHub Actions to GCP using Workload Identity Federation with restricted custom IAM roles.", "subtopics": ["7.27.1 GCP Resource Hierarchy: Organization, Folders, Projects, and Resources; policy inheritance and overriding rules", "7.27.2 GCP Identity and Access Management (IAM): Principal, Roles (Primitive, Predefined, Custom), and Permissions ($service.resource.action)", "7.27.3 IAM Conditions: context-aware access based on date/time, destination IP, resource tags, and request attributes", "7.27.4 Service Accounts: user-managed vs default service accounts, service account keys security vulnerabilities, and keyless architectures", "7.27.5 Workload Identity Federation: mapping external identities (GitHub Actions, AWS) to GCP IAM without static credentials", "7.27.6 GKE Workload Identity: binding Kubernetes ServiceAccounts directly to GCP ServiceAccounts via annotations and OIDC"]}'::jsonb, '["Explain how this implementation prevents: Using default Compute Engine service accounts with broad Editor privileges; committing JSON service account keys to Git.", "How does Cloud Foundations: Google Cloud Platform (GCP) Resource Hierarchy & IAM scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-7-28', 'phase-07-lesson-28-gcp-networking-vpcs-subnets-firewalls-clo', 'module-10', 28, 'Lesson 10.28: GCP Networking: VPCs, Subnets, Firewalls & Cloud NAT', 'Prerequisites: Phase 0, Lesson 7.27', 'Prerequisites: Phase 0, Lesson 7.27 | Subtopics: 6 items', 'Systems project application', 240, 8, 1810.0, 1400.0, '# Lesson 7.28: GCP Networking: VPCs, Subnets, Firewalls & Cloud NAT

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 0, Lesson 7.27
- **Subtopics**:
  - `7.28.1` GCP Virtual Private Cloud (VPC) architecture: global VPCs, regional subnets, and custom-mode vs auto-mode VPC networks
  - `7.28.2` VPC Peering vs Cloud VPN vs Dedicated Interconnect: latency, bandwidth, and transitive routing limitations
  - `7.28.3` VPC Firewall Rules: ingress/egress policies, target tags, service account tags, and priority ordering
  - `7.28.4` Private Google Access and Private Service Connect: accessing GCP APIs and managed databases without public IP addresses
  - `7.28.5` Cloud NAT: outbound internet connectivity for private GKE nodes and VMs without exposing ingress public IPs
  - `7.28.6` Shared VPC architecture: separating central network host projects from application service projects in enterprise setups
- **Key Failure Modes & Edge Cases**: Asymmetric routing drops; creating overlapping CIDR blocks preventing future VPC peering or hybrid interconnects.
- **Verification & Mastery Check**: Construct a multi-region custom-mode VPC with private subnets, Cloud NAT gateways, and Private Google Access routes.
- **Project Application**: InfraBlueprint: Multi-region VPC and network topology.', '{"solution.py": "# Phase 7 // Lesson 7.28: GCP Networking: VPCs, Subnets, Firewalls & Cloud NAT\n\ndef solve():\n    \"\"\"\n    Verification: Construct a multi-region custom-mode VPC with private subnets, Cloud NAT gateways, and Private Googl\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "7.28", "subtopics_count": 6, "verification_criteria": "Construct a multi-region custom-mode VPC with private subnets, Cloud NAT gateways, and Private Google Access routes.", "subtopics": ["7.28.1 GCP Virtual Private Cloud (VPC) architecture: global VPCs, regional subnets, and custom-mode vs auto-mode VPC networks", "7.28.2 VPC Peering vs Cloud VPN vs Dedicated Interconnect: latency, bandwidth, and transitive routing limitations", "7.28.3 VPC Firewall Rules: ingress/egress policies, target tags, service account tags, and priority ordering", "7.28.4 Private Google Access and Private Service Connect: accessing GCP APIs and managed databases without public IP addresses", "7.28.5 Cloud NAT: outbound internet connectivity for private GKE nodes and VMs without exposing ingress public IPs", "7.28.6 Shared VPC architecture: separating central network host projects from application service projects in enterprise setups"]}'::jsonb, '["Explain how this implementation prevents: Asymmetric routing drops; creating overlapping CIDR blocks preventing future VPC peering or hybrid interconnects.", "How does GCP Networking: VPCs, Subnets, Firewalls & Cloud NAT scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-7-29', 'phase-07-lesson-29-gcp-compute-managed-kubernetes-gke-enterp', 'module-10', 29, 'Lesson 10.29: GCP Compute & Managed Kubernetes: GKE Enterprise & Cloud Run', 'Prerequisites: Lesson 7.22, Lesson 7.28', 'Prerequisites: Lesson 7.22, Lesson 7.28 | Subtopics: 6 items', 'Systems project application', 240, 8, 1870.0, 1450.0, '# Lesson 7.29: GCP Compute & Managed Kubernetes: GKE Enterprise & Cloud Run

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 7.22, Lesson 7.28
- **Subtopics**:
  - `7.29.1` Google Kubernetes Engine (GKE) architecture: GKE Standard vs GKE Autopilot (fully managed nodes and control plane)
  - `7.29.2` VPC-Native GKE Clusters: alias IP allocations, direct VPC routability, and eliminating overlay network overhead
  - `7.29.3` Private GKE Clusters: private control plane endpoints, authorized networks, and private worker nodes
  - `7.29.4` Cloud Run internals: serverless containers, scale-to-zero, request concurrency limits, and Knative architecture
  - `7.29.5` Comparing GKE vs Cloud Run: operational overhead, stateful workload support, cold starts, and network connectivity
  - `7.29.6` Cost optimization: preemptible VMs / Spot instances, committed use discounts (CUD), and node auto-provisioning
- **Key Failure Modes & Edge Cases**: Exposing GKE control plane endpoint to 0.0.0.0/0; over-provisioning container resources triggering massive cloud bills.
- **Verification & Mastery Check**: Provision a private, VPC-native GKE cluster with Autopilot security posture, network policies, and Cloud Operations logging.
